// To parse the JSON, install jackson-module-kotlin and do:
//
//   val topLevel = TopLevel.fromJson(jsonString)

package quicktype

import java.time.OffsetDateTime
import java.time.LocalDate
import java.time.OffsetTime

import com.fasterxml.jackson.annotation.*
import com.fasterxml.jackson.core.*
import com.fasterxml.jackson.databind.*
import com.fasterxml.jackson.databind.deser.std.StdDeserializer
import com.fasterxml.jackson.databind.module.SimpleModule
import com.fasterxml.jackson.databind.node.*
import com.fasterxml.jackson.databind.ser.std.StdSerializer
import com.fasterxml.jackson.module.kotlin.*


@Suppress("UNCHECKED_CAST")
private fun <T> ObjectMapper.convert(k: kotlin.reflect.KClass<*>, fromJson: (JsonNode) -> T, toJson: (T) -> String, isUnion: Boolean = false) = registerModule(SimpleModule().apply {
    addSerializer(k.java as Class<T>, object : StdSerializer<T>(k.java as Class<T>) {
            override fun serialize(value: T, gen: JsonGenerator, provider: SerializerProvider) = gen.writeRawValue(toJson(value))
    })
    addDeserializer(k.java as Class<T>, object : StdDeserializer<T>(k.java as Class<T>) {
            override fun deserialize(p: JsonParser, ctxt: DeserializationContext) = fromJson(p.readValueAsTree())
            override fun getNullValue(ctxt: DeserializationContext) = if (isUnion) fromJson(NullNode.instance) else null
    })
})

val mapper = jacksonObjectMapper().apply {
    propertyNamingStrategy = object : PropertyNamingStrategy.PropertyNamingStrategyBase() { override fun translate(name: String) = if (name == "empty") "" else name }
    setSerializationInclusion(JsonInclude.Include.NON_NULL)
    disable(DeserializationFeature.ACCEPT_FLOAT_AS_INT)
    convert(OffsetDateTime::class, { OffsetDateTime.parse(it.asText()) },   { "\"${java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME.format(it)}\"" })
    convert(LocalDate::class,      { LocalDate.parse(it.asText()) },        { "\"${java.time.format.DateTimeFormatter.ISO_LOCAL_DATE.format(it)}\"" })
    convert(OffsetTime::class,     { OffsetTime.parse(it.asText()) },       { "\"${java.time.format.DateTimeFormatter.ISO_OFFSET_TIME.format(it)}\"" })
    convert(Kind::class,           { Kind.fromValue(it.asText()) },         { ObjectMapper().writeValueAsString(it.value) })
    convert(WithEnumEnum::class,   { WithEnumEnum.fromValue(it.asText()) }, { ObjectMapper().writeValueAsString(it.value) })
    convert(Nested::class,         { Nested.fromJson(it) },                 { it.toJson() }, true)
    convert(Numbers::class,        { Numbers.fromJson(it) },                { it.toJson() }, true)
    convert(OnlyDouble::class,     { OnlyDouble.fromJson(it) },             { it.toJson() }, true)
    convert(Stringish::class,      { Stringish.fromJson(it) },              { it.toJson() }, true)
    convert(WithEnumUnion::class,  { WithEnumUnion.fromJson(it) },          { it.toJson() }, true)
    convert(WithMap::class,        { WithMap.fromJson(it) },                { it.toJson() }, true)
    convert(WithObject::class,     { WithObject.fromJson(it) },             { it.toJson() }, true)
}

/**
 * The kitchen sink.
 */
data class TopLevel (
    @get:JsonProperty("", required=true)@field:JsonProperty("", required=true)
    val empty: Long,

    val anyMap: Map<String, Any?>? = null,
    val anything: Any? = null,
    val anythings: List<Any?>? = null,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val at: OffsetTime,

    val byName: Map<String, Point>? = null,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val code: String,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val count: Long,

    /**
     * When it was made.
     */
    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val created: OffsetDateTime,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val day: LocalDate,

    @get:JsonProperty("empty", required=true)@field:JsonProperty("empty", required=true)
    val topLevelEmpty: String,

    val emptyMap: Map<String, Empty>? = null,
    val emptyMapMap: Map<String, Map<String, Empty>>? = null,
    val emptyObject: Empty? = null,
    val fooBar: String? = null,

    @get:JsonProperty("isActive", required=true)@field:JsonProperty("isActive", required=true)
    val isActive: Boolean,

    /**
     * The kind.
     */
    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val kind: Kind,

    val maybeDay: LocalDate? = null,
    val nested: List<List<Nested>>? = null,
    val nothing: Any? = null,
    val numbers: Numbers? = null,
    val onlyDouble: OnlyDouble? = null,
    val optCode: String? = null,
    val optCount: Long? = null,
    val optTags: List<Long>? = null,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val points: List<Point>,

    @get:JsonProperty("price\$")@field:JsonProperty("price\$")
    val price: Double? = null,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val ratio: Double,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val stringish: Stringish,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val tags: List<String>,

    val userURL: String? = null,
    val withEnum: WithEnumUnion? = null,
    val withMap: WithMap? = null,
    val withObject: WithObject? = null
) {
    init {
        require(code.codePointCount(0, code.length) >= 2)
        require(code.codePointCount(0, code.length) <= 8)
        require(Regex("^[A-Z\$]+\\d*\$").containsMatchIn(code))
        require(count >= 0)
        require(count <= 100)
        optCode?.let { require(it.codePointCount(0, it.length) <= 3) }
        optCode?.let { require(Regex("^x").containsMatchIn(it)) }
        optCount?.let { require(it >= 1) }
        optTags?.let { require(it.size <= 2) }
        require(ratio >= -1.5)
        require(ratio <= 1e+21)
        require(tags.size >= 1)
        require(tags.size <= 5)
    }
    fun toJson() = mapper.writeValueAsString(this)

    companion object {
        fun fromJson(json: String) = mapper.readValue<TopLevel>(json)
    }
}

/**
 * A point.
 */
data class Point (
    val label: String? = null,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val x: Double,

    @get:JsonProperty(required=true)@field:JsonProperty(required=true)
    val y: Double
)

typealias Empty = ObjectNode

/**
 * The kind.
 */
enum class Kind(val value: String) {
    FirstKind("first-kind"),
    Second("SECOND"),
    ThirdKind("third_kind"),
    Dollar("\$dollar"),
    WithQuote("with \"quote\"");

    companion object {
        fun fromValue(value: String): Kind = when (value) {
            "first-kind"     -> FirstKind
            "SECOND"         -> Second
            "third_kind"     -> ThirdKind
            "\$dollar"       -> Dollar
            "with \"quote\"" -> WithQuote
            else             -> throw IllegalArgumentException()
        }
    }
}

sealed class Nested {
    class IntegerValue(val value: Long)  : Nested()
    class StringValue(val value: String) : Nested()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is IntegerValue -> this.value
        is StringValue  -> this.value
    })

    companion object {
        fun fromJson(jn: JsonNode): Nested = when (jn) {
            is IntNode, is LongNode -> IntegerValue(mapper.convertValue(jn))
            is TextNode             -> StringValue(mapper.convertValue(jn))
            else                    -> throw IllegalArgumentException()
        }
    }
}

sealed class Numbers {
    class BoolValue(val value: Boolean)  : Numbers()
    class DoubleValue(val value: Double) : Numbers()
    class IntegerValue(val value: Long)  : Numbers()
    class NullValue()                    : Numbers()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is BoolValue    -> this.value
        is DoubleValue  -> this.value
        is IntegerValue -> this.value
        is NullValue    -> null
    })

    companion object {
        fun fromJson(jn: JsonNode): Numbers = when (jn) {
            is BooleanNode                         -> BoolValue(mapper.convertValue(jn))
            is IntNode, is LongNode, is DoubleNode -> DoubleValue(mapper.convertValue(jn))
            is IntNode, is LongNode                -> IntegerValue(mapper.convertValue(jn))
            is NullNode                            -> NullValue()
            else                                   -> throw IllegalArgumentException()
        }
    }
}

sealed class OnlyDouble {
    class DoubleValue(val value: Double) : OnlyDouble()
    class StringValue(val value: String) : OnlyDouble()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is DoubleValue -> this.value
        is StringValue -> this.value
    })

    companion object {
        fun fromJson(jn: JsonNode): OnlyDouble = when (jn) {
            is IntNode, is LongNode, is DoubleNode -> DoubleValue(mapper.convertValue(jn))
            is TextNode                            -> StringValue(mapper.convertValue(jn))
            else                                   -> throw IllegalArgumentException()
        }
    }
}

sealed class Stringish {
    class DateTimeValue(val value: OffsetDateTime) : Stringish()
    class DateValue(val value: LocalDate)          : Stringish()
    class IntegerValue(val value: Long)            : Stringish()
    class TimeValue(val value: OffsetTime)         : Stringish()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is DateTimeValue -> this.value
        is DateValue     -> this.value
        is IntegerValue  -> this.value
        is TimeValue     -> this.value
    })

    companion object {
        fun fromJson(jn: JsonNode): Stringish = when (jn) {
            is TextNode             -> try { DateTimeValue(mapper.convertValue(jn)) } catch (e: Exception) { try { DateValue(mapper.convertValue(jn)) } catch (e: Exception) { TimeValue(mapper.convertValue(jn)) } }
            is IntNode, is LongNode -> IntegerValue(mapper.convertValue(jn))
            else                    -> throw IllegalArgumentException()
        }
    }
}

sealed class WithEnumUnion {
    class DateValue(val value: LocalDate)    : WithEnumUnion()
    class EnumValue(val value: WithEnumEnum) : WithEnumUnion()
    class IntegerValue(val value: Long)      : WithEnumUnion()
    class NullValue()                        : WithEnumUnion()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is DateValue    -> this.value
        is EnumValue    -> this.value
        is IntegerValue -> this.value
        is NullValue    -> null
    })

    companion object {
        fun fromJson(jn: JsonNode): WithEnumUnion = when (jn) {
            is TextNode             -> try { DateValue(mapper.convertValue(jn)) } catch (e: Exception) { EnumValue(mapper.convertValue(jn)) }
            is IntNode, is LongNode -> IntegerValue(mapper.convertValue(jn))
            is NullNode             -> NullValue()
            else                    -> throw IllegalArgumentException()
        }
    }
}

enum class WithEnumEnum(val value: String) {
    Red("red"),
    Green("green");

    companion object {
        fun fromValue(value: String): WithEnumEnum = when (value) {
            "red"   -> Red
            "green" -> Green
            else    -> throw IllegalArgumentException()
        }
    }
}

sealed class WithMap {
    class IntegerMapValue(val value: Map<String, Long>) : WithMap()
    class StringValue(val value: String)                : WithMap()
    class NullValue()                                   : WithMap()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is IntegerMapValue -> this.value
        is StringValue     -> this.value
        is NullValue       -> null
    })

    companion object {
        fun fromJson(jn: JsonNode): WithMap = when (jn) {
            is ObjectNode -> IntegerMapValue(mapper.convertValue(jn))
            is TextNode   -> StringValue(mapper.convertValue(jn))
            is NullNode   -> NullValue()
            else          -> throw IllegalArgumentException()
        }
    }
}

sealed class WithObject {
    class BoolValue(val value: Boolean)                        : WithObject()
    class PointValue(val value: Point)                         : WithObject()
    class StringArrayArrayValue(val value: List<List<String>>) : WithObject()

    fun toJson(): String = mapper.writeValueAsString(when (this) {
        is BoolValue             -> this.value
        is PointValue            -> this.value
        is StringArrayArrayValue -> this.value
    })

    companion object {
        fun fromJson(jn: JsonNode): WithObject = when (jn) {
            is BooleanNode -> BoolValue(mapper.convertValue(jn))
            is ObjectNode  -> PointValue(mapper.convertValue(jn))
            is ArrayNode   -> StringArrayArrayValue(mapper.convertValue(jn))
            else           -> throw IllegalArgumentException()
        }
    }
}

// To parse the JSON, install Klaxon and do:
//
//   val topLevel = TopLevel.fromJson(jsonString)

package quicktype

import java.time.OffsetDateTime
import java.time.LocalDate
import java.time.OffsetTime

import com.beust.klaxon.*

private fun <T> Klaxon.convert(k: kotlin.reflect.KClass<*>, fromJson: (JsonValue) -> T, toJson: (T) -> String, isUnion: Boolean = false) =
    this.converter(object: Converter {
        @Suppress("UNCHECKED_CAST")
        override fun toJson(value: Any)        = toJson(value as T)
        override fun fromJson(jv: JsonValue)   = if (isUnion && jv.inside is JsonArray<*>) (jv.inside as JsonArray<*>).map { fromJson(JsonValue(it, null, null, this@convert)) } else fromJson(jv) as Any
        override fun canConvert(cls: Class<*>) = cls == k.java || (isUnion && cls.superclass == k.java)
    })

// Klaxon cannot deserialize map values typed as JsonObject, so fields
// holding such maps are converted at the field level instead.
@Target(AnnotationTarget.FIELD)
private annotation class KlaxonJsonObjectMap

private val jsonObjectMapConverter: Converter = object : Converter {
    override fun canConvert(cls: Class<*>) = true
    override fun fromJson(jv: JsonValue)   = jv.obj!!
    override fun toJson(value: Any)        = klaxon.toJsonString(value)
}

private val klaxon = Klaxon()
    .convert(OffsetDateTime::class, { OffsetDateTime.parse(it.string!!) },   { "\"${java.time.format.DateTimeFormatter.ISO_OFFSET_DATE_TIME.format(it)}\"" })
    .convert(LocalDate::class,      { LocalDate.parse(it.string!!) },        { "\"${java.time.format.DateTimeFormatter.ISO_LOCAL_DATE.format(it)}\"" })
    .convert(OffsetTime::class,     { OffsetTime.parse(it.string!!) },       { "\"${java.time.format.DateTimeFormatter.ISO_OFFSET_TIME.format(it)}\"" })
    .convert(JsonObject::class,     { it.obj!! },                            { it.toJsonString() })
    .convert(Kind::class,           { Kind.fromValue(it.string!!) },         { Klaxon().toJsonString(it.value) })
    .convert(WithEnumEnum::class,   { WithEnumEnum.fromValue(it.string!!) }, { Klaxon().toJsonString(it.value) })
    .convert(Nested::class,         { Nested.fromJson(it) },                 { it.toJson() }, true)
    .convert(Numbers::class,        { Numbers.fromJson(it) },                { it.toJson() }, true)
    .convert(OnlyDouble::class,     { OnlyDouble.fromJson(it) },             { it.toJson() }, true)
    .convert(Stringish::class,      { Stringish.fromJson(it) },              { it.toJson() }, true)
    .convert(WithEnumUnion::class,  { WithEnumUnion.fromJson(it) },          { it.toJson() }, true)
    .convert(WithMap::class,        { WithMap.fromJson(it) },                { it.toJson() }, true)
    .convert(WithObject::class,     { WithObject.fromJson(it) },             { it.toJson() }, true)
    .fieldConverter(KlaxonJsonObjectMap::class, jsonObjectMapConverter)

/**
 * The kitchen sink.
 */
data class TopLevel (
    @Json(name = "")
    val empty: Long,

    val anyMap: Map<String, Any?>? = null,
    val anything: Any? = null,
    val anythings: List<Any?>? = null,
    val at: OffsetTime,
    val byName: Map<String, Point>? = null,
    val code: String,
    val count: Long,

    /**
     * When it was made.
     */
    val created: OffsetDateTime,

    val day: LocalDate,

    @Json(name = "empty")
    val topLevelEmpty: String,

    @KlaxonJsonObjectMap
    val emptyMap: Map<String, Empty>? = null,

    @KlaxonJsonObjectMap
    val emptyMapMap: Map<String, Map<String, Empty>>? = null,

    val emptyObject: Empty? = null,
    val fooBar: String? = null,
    val isActive: Boolean,

    /**
     * The kind.
     */
    val kind: Kind,

    val maybeDay: LocalDate? = null,
    val nested: List<List<Nested>>? = null,
    val nothing: Any? = null,
    val numbers: Numbers? = null,
    val onlyDouble: OnlyDouble? = null,
    val optCode: String? = null,
    val optCount: Long? = null,
    val optTags: List<Long>? = null,
    val points: List<Point>,

    @Json(name = "price\$")
    val price: Double? = null,

    val ratio: Double,
    val stringish: Stringish,
    val tags: List<String>,
    val userURL: String? = null,
    val withEnum: WithEnumUnion? = null,
    val withMap: WithMap? = null,
    val withObject: WithObject? = null
) {
    init {
        require(code.codePointCount(0, code.length) >= 2)
    }
    init {
        require(code.codePointCount(0, code.length) <= 8)
    }
    init {
        require(Regex("^[A-Z\$]+\\d*\$").containsMatchIn(code))
    }
    init {
        require(count >= 0)
    }
    init {
        require(count <= 100)
    }
    init {
        optCode?.let { require(it.codePointCount(0, it.length) <= 3) }
    }
    init {
        optCode?.let { require(Regex("^x").containsMatchIn(it)) }
    }
    init {
        optCount?.let { require(it >= 1) }
    }
    init {
        optTags?.let { require(it.size <= 2) }
    }
    init {
        require(ratio >= -1.5)
    }
    init {
        require(ratio <= 1e+21)
    }
    init {
        require(tags.size >= 1)
    }
    init {
        require(tags.size <= 5)
    }
    public fun toJson() = klaxon.toJsonString(this)

    companion object {
        public fun fromJson(json: String) = klaxon.parse<TopLevel>(json)
    }
}

