typealias Empty = JsonObject

/**
 * The kind.
 */
enum class Kind(val value: String) {
    FirstKind("first-kind"),
    Second("SECOND"),
    ThirdKind("third_kind"),
    Dollar("\$dollar"),
    WithQuote("with \"quote\"");

    companion object {
        public fun fromValue(value: String): Kind = when (value) {
            "first-kind"     -> FirstKind
            "SECOND"         -> Second
            "third_kind"     -> ThirdKind
            "\$dollar"       -> Dollar
            "with \"quote\"" -> WithQuote
            else             -> throw IllegalArgumentException()
        }
    }
}

sealed class Nested {
    class IntegerValue(val value: Long)  : Nested()
    class StringValue(val value: String) : Nested()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is IntegerValue -> this.value
        is StringValue  -> this.value
    })

    companion object {
        public fun fromJson(jv: JsonValue): Nested = when (jv.inside) {
            is Int, is Long -> IntegerValue((jv.int?.toLong() ?: jv.longValue)!!)
            is String       -> StringValue(jv.string!!)
            else            -> throw IllegalArgumentException()
        }
    }
}

sealed class Numbers {
    class BoolValue(val value: Boolean)  : Numbers()
    class DoubleValue(val value: Double) : Numbers()
    class IntegerValue(val value: Long)  : Numbers()
    class NullValue()                    : Numbers()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is BoolValue    -> this.value
        is DoubleValue  -> this.value
        is IntegerValue -> this.value
        is NullValue    -> "null"
    })

    companion object {
        public fun fromJson(jv: JsonValue): Numbers = when (jv.inside) {
            is Boolean      -> BoolValue(jv.boolean!!)
            is Double       -> DoubleValue(jv.double ?: jv.int?.toDouble() ?: jv.longValue?.toDouble()!!)
            is Int, is Long -> IntegerValue((jv.int?.toLong() ?: jv.longValue)!!)
            null            -> NullValue()
            else            -> throw IllegalArgumentException()
        }
    }
}

sealed class OnlyDouble {
    class DoubleValue(val value: Double) : OnlyDouble()
    class StringValue(val value: String) : OnlyDouble()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is DoubleValue -> this.value
        is StringValue -> this.value
    })

    companion object {
        public fun fromJson(jv: JsonValue): OnlyDouble = when (jv.inside) {
            is Double, is Int, is Long -> DoubleValue(jv.double ?: jv.int?.toDouble() ?: jv.longValue?.toDouble()!!)
            is String                  -> StringValue(jv.string!!)
            else                       -> throw IllegalArgumentException()
        }
    }
}

sealed class Stringish {
    class DateTimeValue(val value: OffsetDateTime) : Stringish()
    class DateValue(val value: LocalDate)          : Stringish()
    class IntegerValue(val value: Long)            : Stringish()
    class TimeValue(val value: OffsetTime)         : Stringish()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is DateTimeValue -> this.value
        is DateValue     -> this.value
        is IntegerValue  -> this.value
        is TimeValue     -> this.value
    })

    companion object {
        public fun fromJson(jv: JsonValue): Stringish = when (jv.inside) {
            is String       -> try { DateTimeValue(jv.string?.let { OffsetDateTime.parse(it) }!!) } catch (e: Exception) { try { DateValue(jv.string?.let { LocalDate.parse(it) }!!) } catch (e: Exception) { TimeValue(jv.string?.let { OffsetTime.parse(it) }!!) } }
            is Int, is Long -> IntegerValue((jv.int?.toLong() ?: jv.longValue)!!)
            else            -> throw IllegalArgumentException()
        }
    }
}

sealed class WithEnumUnion {
    class DateValue(val value: LocalDate)    : WithEnumUnion()
    class EnumValue(val value: WithEnumEnum) : WithEnumUnion()
    class IntegerValue(val value: Long)      : WithEnumUnion()
    class NullValue()                        : WithEnumUnion()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is DateValue    -> this.value
        is EnumValue    -> this.value
        is IntegerValue -> this.value
        is NullValue    -> "null"
    })

    companion object {
        public fun fromJson(jv: JsonValue): WithEnumUnion = when (jv.inside) {
            is String       -> try { DateValue(jv.string?.let { LocalDate.parse(it) }!!) } catch (e: Exception) { EnumValue(jv.string?.let { WithEnumEnum.fromValue(it) }!!) }
            is Int, is Long -> IntegerValue((jv.int?.toLong() ?: jv.longValue)!!)
            null            -> NullValue()
            else            -> throw IllegalArgumentException()
        }
    }
}

enum class WithEnumEnum(val value: String) {
    Red("red"),
    Green("green");

    companion object {
        public fun fromValue(value: String): WithEnumEnum = when (value) {
            "red"   -> Red
            "green" -> Green
            else    -> throw IllegalArgumentException()
        }
    }
}

sealed class WithMap {
    class IntegerMapValue(val value: Map<String, Long>) : WithMap()
    class StringValue(val value: String)                : WithMap()
    class NullValue()                                   : WithMap()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is IntegerMapValue -> this.value
        is StringValue     -> this.value
        is NullValue       -> "null"
    })

    companion object {
        public fun fromJson(jv: JsonValue): WithMap = when (jv.inside) {
            is JsonObject -> IntegerMapValue(jv.obj?.let { klaxon.parseFromJsonObject<Map<String, Long>>(it) }!!)
            is String     -> StringValue(jv.string!!)
            null          -> NullValue()
            else          -> throw IllegalArgumentException()
        }
    }
}

sealed class WithObject {
    class BoolValue(val value: Boolean)                        : WithObject()
    class PointValue(val value: Point)                         : WithObject()
    class StringArrayArrayValue(val value: List<List<String>>) : WithObject()

    public fun toJson(): String = klaxon.toJsonString(when (this) {
        is BoolValue             -> this.value
        is PointValue            -> this.value
        is StringArrayArrayValue -> this.value
    })

    companion object {
        public fun fromJson(jv: JsonValue): WithObject = when (jv.inside) {
            is Boolean      -> BoolValue(jv.boolean!!)
            is JsonObject   -> PointValue(jv.obj?.let { klaxon.parseFromJsonObject<Point>(it) }!!)
            is JsonArray<*> -> StringArrayArrayValue(jv.array?.let { klaxon.parseFromJsonArray<List<String>>(it) }!!)
            else            -> throw IllegalArgumentException()
        }
    }
}

