    convert(OnlyDouble::class,     { OnlyDouble.fromJson(it) },             { it.toJson() }, true)
    convert(Stringish::class,      { Stringish.fromJson(it) },              { it.toJson() }, true)
    convert(WithEnumUnion::class,  { WithEnumUnion.fromJson(it) },          { it.toJson() }, true)
